/**
 * The colorectal cancer roadmap and the open questions (ideas) for the September 2026 deep dive. Every dated claim in
 * the steps points at a paper record in the colorectal-evidence files or in the wider corpus, or at a
 * ClinicalTrials.gov record; the `watch` dates are quoted from the registry as read on 2026-09-24 and are not
 * predictions. The id carries the `-roadmap` suffix because `colorectal` is the cancer record and ids are global; the
 * early detection, surgery, radiation and immunotherapy roadmaps are the cross-cancer routes this one joins.
 */
type R = Omit<RoadmapInput, "kind" | "asOf">;
const r = (x: R): RoadmapInput => ({ kind: "roadmap", asOf, ...x });
type I = Omit<IdeaInput, "kind" | "asOf">;
const idea = (x: I): IdeaInput => ({ kind: "idea", asOf, tags: ["colorectal-evidence"], ...x });

